import { IsOptional, IsUUID } from 'class-validator';
import { IsEncoded } from '../../../common/validation';

export class CreateVaultDto {
  /** Generated by the client: the vault's key wraps and label are bound to it. */
  @IsUUID('4')
  id: string;

  /** The vault key under the vault passphrase, then sealed to the creator's public key. */
  @IsEncoded(512)
  wrappedKey: string;

  /** Argon2id salt for the vault passphrase. */
  @IsEncoded(64)
  kdfSalt: string;

  @IsOptional()
  @IsEncoded(1024)
  labelEncrypted?: string;

  @IsOptional()
  @IsEncoded(32)
  labelNonce?: string;
}
